    const i = Math.floor(rng() * S);
    const o = owner[i];
    if (rng() < 0.65) {
      const q = Math.floor(rng() * P);
      if (q === o || !elig[q][i]) continue;
      const nq = insertSorted(ctx, lists[q], i);
