      const no = o >= 0 ? removeFrom(lists[o], i) : null;
      const sq = personScore(ctx, q, nq), so = o >= 0 ? personScore(ctx, o, no) : 0;
      let delta = sq - pScore[q] + (o >= 0 ? so - pScore[o] : -BIG * ((slots[i].end - slots[i].start) / 60));
      if (delta < 0 || rng() < Math.exp(-delta / T)) {
