    for (let p = 0; p < P; p++) if (elig[p][i]) m = Math.min(m, burden * staff[p].wage * mFloor * paidMinutes(o, s) / 60);
    return m === Infinity ? 0 : m; // nobody can take it: it stays open, which the coverage bound already charges
  });
